// Lista e kategorive dhe temave — shto/ndrysho sipas nevojës
const categories = [
  {
    name: 'Ekonomi',
    topics: [
      'Inflacioni dhe ndikimi i tij në buxhetin familjar',
      'Rritja ekonomike dhe tregu i punës në Shqipëri',
      'Eksportet dhe importet: si ndikojnë në ekonominë vendase',
      'Remitancat dhe roli i tyre në ekonominë shqiptare',
      'Turizmi si motor i ekonomisë'
    ]
  },
  {
    name: 'Kredi',
    topics: [
      'Si të merrni një kredi hipotekare: hapat kryesorë',
      'Kredi konsumatore: çfarë duhet të dini para se të aplikoni',
      'Norma e interesit: fikse apo e ndryshueshme?',
      'Si të përmirësoni historikun tuaj kreditor',
      'Rifinancimi i kredisë: kur ia vlen?'
    ]
  },
  {
    name: 'Banka',
    topics: [
      'Si të zgjidhni bankën e duhur për nevojat tuaja',
      'Llogaritë e kursimit dhe depozitat me afat',
      'Shërbimet bankare online: siguria dhe përfitimet',
      'Komisionet bankare: si të kurseni',
      'Kartat e kreditit kundrejt kartave të debitit'
    ]
  },
  {
    name: 'Investime',
    topics: [
      'Bazat e investimit për fillestarët',
      'Investimi në pasuri të paluajtshme në Shqipëri',
      'Obligacionet qeveritare: një investim i sigurt?',
      'Diversifikimi i portofolit: pse është i rëndësishëm',
      'Fondet e investimit: si funksionojnë'
    ]
  },
  {
    name: 'Financa Personale',
    topics: [
      'Si të krijoni një buxhet mujor efektiv',
      'Fondi i emergjencës: sa duhet të kurseni',
      'Planifikimi i pensionit: fillo herët',
      'Si të dilni nga borxhet: strategji praktike',
      'Edukimi financiar për të rinjtë'
    ]
  },
  {
    name: 'Sigurime',
    topics: [
      'Sigurimi i jetës: a ju nevojitet vërtet?',
      'Sigurimi i shtëpisë dhe pronës',
      'Sigurimi shëndetësor privat në Shqipëri',
      'Sigurimi i makinës: TPL dhe kasko',
      'Si të zgjidhni policën e duhur të sigurimit'
    ]
  }
];

// Rrotullim: çdo ditë kategori tjetër, çdo cikël temë tjetër
const now = new Date();
const start = new Date(now.getFullYear(), 0, 0);
const dayOfYear = Math.floor((now - start) / 86400000);
const cat = categories[dayOfYear % categories.length];
const topic = cat.topics[Math.floor(dayOfYear / categories.length) % cat.topics.length];

// Trupi i kërkesës për Claude API (Anthropic Messages API)
const claudeBody = {
  model: 'claude-opus-4-8',
  max_tokens: 8000,
  system: [
    'Ti je gazetar dhe ekspert i ekonomisë e financave që shkruan për një portal informativ shqiptar.',
    'Shkruan artikuj informues, të saktë dhe të lexueshëm për publikun e gjerë, në gjuhën shqipe standarde.',
    'Rregulla të detyrueshme:',
    '- Artikulli duhet të ketë MAKSIMUMI 500 fjalë. Kjo është kufi i prerë.',
    '- content_html duhet të jetë HTML i pastër: vetëm <h2>, <h3>, <p>, <ul>, <li>, <strong>. Pa <h1>, pa <html>, <head> ose <body>.',
    '- Titulli duhet të jetë tërheqës, maksimumi 70 karaktere, pa thonjëza.',
    '- excerpt: 1-2 fjali përmbledhëse (max 40 fjalë).',
    '- Mos shpik statistika ose shifra të sakta që nuk i di me siguri; përdor formulime të përgjithshme.',
    '- Ton profesional por i afërt, i përshtatur për lexuesin shqiptar.'
  ].join('\n'),
  messages: [
    {
      role: 'user',
      content: `Shkruaj një artikull për kategorinë "${cat.name}" me temën: "${topic}". Mbaje artikullin nën 500 fjalë.`
    }
  ],
  output_config: {
    format: {
      type: 'json_schema',
      schema: {
        type: 'object',
        properties: {
          title: { type: 'string', description: 'Titulli i artikullit, max 70 karaktere' },
          content_html: { type: 'string', description: 'Përmbajtja e artikullit në HTML, max 500 fjalë' },
          excerpt: { type: 'string', description: 'Përmbledhje e shkurtër, 1-2 fjali' }
        },
        required: ['title', 'content_html', 'excerpt'],
        additionalProperties: false
      }
    }
  }
};

return [{ json: { category: cat.name, topic, claudeBody } }];

const resp = $input.first().json;

if (resp.stop_reason === 'refusal') {
  throw new Error('Claude e refuzoi kërkesën — provo një temë tjetër.');
}
if (resp.stop_reason === 'max_tokens') {
  throw new Error('Përgjigja u pre në mes — rrit max_tokens në nyjen "Zgjidh Kategorinë".');
}

const textBlock = (resp.content || []).find(b => b.type === 'text');
if (!textBlock) {
  throw new Error('Nuk u gjet përmbajtje tekstuale në përgjigjen e Claude.');
}

const article = JSON.parse(textBlock.text);

// Siguri shtesë: kufizo në max 500 fjalë duke hequr paragrafë nga fundi
const countWords = (html) =>
  html.replace(/<[^>]+>/g, ' ').trim().split(/\s+/).filter(Boolean).length;

if (countWords(article.content_html) > 500) {
  const parts = article.content_html.split(/(?<=<\/p>)/);
  while (parts.length > 1 && countWords(parts.join('')) > 500) {
    parts.pop();
  }
  article.content_html = parts.join('');
}

const meta = $('Zgjidh Kategorinë').first().json;

return [{
  json: {
    title: article.title,
    content: article.content_html,
    excerpt: article.excerpt,
    category: meta.category,
    topic: meta.topic,
    wordCount: countWords(article.content_html)
  }
}];

const wanted = $('Përpuno Përgjigjen').first().json.category.toLowerCase();
const match = $input.all()
  .map(i => i.json)
  .find(c => c && c.name && c.name.toLowerCase() === wanted);

return [{ json: { categoryId: match ? match.id : null } }];

